import java.util.List;
import org.junit.jupiter.api.Test;

class TableChecksTest {
    @Test
    void reportsEachDuplicateOnceInOrder() {
        assertEquals(List.of("INV-1", "INV-2"),
            TableChecks.duplicates(List.of("INV-1", "INV-2", "INV-1", "INV-3", "INV-2", "INV-1")));
    }

    @Test
    void orderIsBySecondOccurrence() {
        assertEquals(List.of("b", "a"), TableChecks.duplicates(List.of("a", "b", "b", "a")));
    }

    @Test
    void noDuplicatesGivesEmptyList() {
        assertEquals(List.of(), TableChecks.duplicates(List.of("x", "y")));
    }
}

