import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class StatusCounter {
    public static Map<String, Integer> count(List<String> statuses) {
        Map<String, Integer> counts = new TreeMap<>();
        for (int i = 0; i < statuses.size(); i++) {
            String s = statuses.get(i);
            if (s == null || s.isBlank()) {
                throw new IllegalArgumentException("blank status at row " + i);
            }
            counts.merge(s.trim().toUpperCase(), 1, Integer::sum);
        }
        return counts;
    }
}

