import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class StatusCounterTest {
    @Test
    void countsCaseInsensitively() {
        Map<String, Integer> c = StatusCounter.count(List.of(" paid", "PAID", "pending", "Failed"));
        assertEquals(Map.of("FAILED", 1, "PAID", 2, "PENDING", 1), c);
    }

    @Test
    void keysAreSorted() {
        Map<String, Integer> c = StatusCounter.count(List.of("b", "a", "c"));
        assertEquals(List.of("A", "B", "C"), List.copyOf(c.keySet()));
    }

    @Test
    void blankStatusReportsRow() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
            () -> StatusCounter.count(Arrays.asList("paid", "paid", "  ")));
        assertTrue(e.getMessage().contains("row 2"), e.getMessage());
    }
}
